    visited = set()
    queue = []
    for name in sorted_root_deps:
        if name not in visited:
            visited.add(name)
            queue.append((name, [ROOT, name]))

    while queue:
        node, path = queue.pop(0)
        if node == target:
            return path
        for dep in sorted(packages_map[node]["deps"]):
            if dep in visited:
                continue
            visited.add(dep)
            queue.append((dep, path + [dep]))
    return []

